export function ColorTool(): HTMLElement {
  const wrapper = document.createElement("div")
  wrapper.className = "tool color-tool"

  const input = document.createElement("input")
  input.type = "color"

  const pickButton = document.createElement("button")
  pickButton.textContent = "Pick from page"

  const copyButton = document.createElement("button")
  copyButton.textContent = "Copy HEX"

  const output = document.createElement("p")
  output.textContent = "Pick a color…"

  let currentHex: string | null = null

  input.addEventListener("input", () => {
    showColor(input.value)
  })

  pickButton.addEventListener("click", async () => {
    const hex = await pickColorFromPage()
    if (hex) {
      input.value = hex
      showColor(hex)
    }
  })

  copyButton.addEventListener("click", () => {
    if (currentHex) {
      navigator.clipboard.writeText(currentHex).then(() => {
        copyButton.textContent = "Copied!"
        setTimeout(() => (copyButton.textContent = "Copy HEX"), 1000)
      })
    }
  })

  function showColor(hex: string) {
    currentHex = hex
    output.textContent = `HEX: ${hex}, RGB: ${hexToRgb(hex)}`
  }

  wrapper.appendChild(input)
  wrapper.appendChild(pickButton)
  wrapper.appendChild(copyButton)
  wrapper.appendChild(output)
  return wrapper
}

async function pickColorFromPage(): Promise<string | null> {
  if ("EyeDropper" in window) {
    const eyeDropper = new (window as any).EyeDropper()
    try {
      const result = await eyeDropper.open()
      return result.sRGBHex
    } catch {
      return null
    }
  }
  return null
}

function hexToRgb(hex: string): string {
  const bigint = parseInt(hex.slice(1), 16)
  const r = (bigint >> 16) & 255
  const g = (bigint >> 8) & 255
  const b = bigint & 255
  return `rgb(${r}, ${g}, ${b})`
}
